  Theorem akernel_main : akernel s0 model.
  Proof.
    (* #38 RESERVED-CEILING-CLASS: [akernel] is [akernel_pre /\ akernel_resx]
       ([As/AllocRepX.v]).  The recorded body below proves [akernel_pre]: its
       first conjunct ranges over [segments_reserved asegs], and the body's one
       spelled-out copy of that conjunct (the type of the [conj] that takes [ak1])
       was rewritten from [vm_reserved] to it; [ak1]'s restated domain
       [segments_reserved ASEGS] is convertible with it ([As/AsMainIface.v:31 asegs_ASEGS]).  The body
       was recorded against the flat [akernel s0 model]; its outer cast and the motives
       of its eliminations now name the conjunction it builds instead.  The second half
       is the producer's split, which [ak_reserved] re-exports verbatim;
       [resx_entry_ok]'s fourth and fifth components are [img_hi ASAN_H <= fst e]
       and [KHI + 4096 <= fst e], which are [AIMG_TOP] and [AHI_LO + 4096] up to
       delta. *)
    (* The discharge is SEARCH-BASED, not positional: [resx_entry_ok] is a
       conjunction whose arity has already moved once at #38, and a numbered
       intro pattern would break again the next time it does. *)
    split; [ | destruct ak_reserved as [rx [Hr [Hok [Hlen Hsz]]]]; exists rx;
               split; [exact Hr|]; split;
               [ intros e He; pose proof (proj1 (Forall_forall _ _) Hok e He) as Q;
                 (* [resx_entry_ok] is a definition: the [_ /\ _] match below sees its seven parts only unfolded *)
                 unfold resx_entry_ok in Q;
                 repeat match goal with H : _ /\ _ |- _ => destruct H end;
                 repeat split; assumption
               | split;
                 [ revert Hlen; cbn [n_resx ASAN_H]; lia
                 | split;
                   [ (* the goal's [zsum] is the one [AllocRepX] sees ([SecGap.zsum]), not this file's
                        ([AsanAllocModel.zsum]), so the sum is related to [sum_sizes] in the goal's own term *)
                    revert Hsz; unfold resx_bytes; cbn [p_resx ASAN_H];
                    match goal with |- _ -> Z.le ?z _ =>
                      assert (ZS : z = sum_sizes rx)
                        by (clear; induction rx as [|e rx IH]; [reflexivity | cbn; rewrite IH; reflexivity])
                    end; lia
                   | (* #38 RESERVED-CEILING-CLASS: the added MAPS-vs-RESERVED
                        disjointness conjunct of [akernel_resx].  This is the ONLY
                        from-scratch site for it in this mirror, because the conjunct
                        is INIT-ONLY: it is a property of [vm_maps]/[vm_reserved] at
                        the launch model and every later transition carries it
                        unchanged.  It is the model's own [co_mres]
                        ([As/AsanPlanSound.v:420]) with its two [Forall]s eliminated
                        into the two [In] quantifiers [akernel_resx] spells, and
                        [iv_disjoint] ([As/AsanPlanSound.v:60-62]) unfolded to the
                        same disjunction - so this branch TRANSPORTS a model fact and
                        derives nothing.  [HC] is the [cs_ok] this Section already
                        holds, so no new hypothesis is taken.
                        Like the per-entry branch above it is POSITION-INDEPENDENT:
                        it names [co_mres] and [iv_disjoint] rather than projecting
                        [co_res] by position, so a further arity move in [cs_ok]
                        fails HERE, by name. *)
                     intros iv Hiv e He;
                     pose proof (proj1 (Forall_forall _ _)
                                   (co_mres _ _ _ _ _ _ _ _ _ _ _ HC) iv Hiv) as HDv;
                     pose proof (proj1 (Forall_forall _ _) HDv e He) as D;
                     unfold iv_disjoint in D; exact D ] ] ] ].
